import{_ as t}from"./chunks/log-bb-player.pc.en.i6OweW45.js";import{_ as o,o as s,c as r,a5 as n}from"./chunks/framework.D47SInms.js";const a="/RBQ/nightly/images/app/log-rt.pc.en.png",i="/RBQ/nightly/images/app/log-sys.pc.en.png",f=JSON.parse('{"title":"Logs","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/logs.md","filePath":"manual/gui/logs.md","lastUpdated":1791600043000}'),l={name:"manual/gui/logs.md"};function h(g,e,d,c,p,m){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h1><p>Open <strong>Logs</strong> with the <code>Logs</code> tile on the hub. The tile works without a robot too: <strong>System Log</strong> and <strong>Black Box</strong> load once the robot is connected, and until then <strong>Black Box</strong> opens on <strong>Library</strong> — the sessions you saved on this device. A red <strong>ERROR</strong> / <strong>FATAL</strong> toast or a row in the alert badge popover on the control home also opens it (see <a href="#real-time">Real Time</a>). Every user can open it. It has three tabs, and the same filter bar works in all of them.</p><p><img src="'+a+'" alt="Real Time tab"></p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Content</th></tr></thead><tbody><tr><td><strong>Real Time</strong></td><td>Messages streamed from the robot while the app is connected</td></tr><tr><td><strong>System Log</strong></td><td>Log files stored on the robot, one per day</td></tr><tr><td><strong>Black Box</strong></td><td>Recordings saved when the robot fell, when control was turned off, or when you pressed <strong>Save now</strong> — 30 s of motion data plus the system log of that moment</td></tr></tbody></table><p>A dot next to the tabs shows the log link: <strong>Connected</strong>, <strong>Connecting</strong>, or <strong>Disconnected</strong>.</p><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><ul><li><strong>LEVEL</strong> chips — <strong>TRACE</strong>, <strong>DEBUG</strong>, <strong>INFO</strong>, <strong>SUCCESS</strong>, <strong>WARNING</strong>, <strong>ERROR</strong>, <strong>FATAL</strong>. Tap a chip to hide that level; tap again to show it.</li><li><strong>PROC</strong> chips — one per process in the current source, each in its own color. Tap to hide or show.</li><li><strong>Search</strong> — filters on the message text or the process name.</li><li>The count at the right of the action bar reads <em>shown / total</em> <strong>lines</strong>. Very long files show only the latest 2,500 lines, with a notice at the top.</li></ul><h2 id="real-time" tabindex="-1">Real Time <a class="header-anchor" href="#real-time" aria-label="Permalink to &quot;Real Time&quot;">​</a></h2><ul><li><strong>Auto-scroll</strong> — keeps the newest line in view; turn it off to read older lines.</li><li><strong>Save</strong> — saves the currently filtered lines to your device.</li><li>Tapping a red <strong>ERROR</strong> / <strong>FATAL</strong> toast, or a row in the alert badge popover, opens this tab with that line highlighted so you can see what happened around it.</li></ul><h2 id="system-log" tabindex="-1">System Log <a class="header-anchor" href="#system-log" aria-label="Permalink to &quot;System Log&quot;">​</a></h2><p><img src="'+i+'" alt="System Log tab"></p><ol><li><strong>Fetch</strong> — loads the list of days from the robot (this runs by itself the first time you open the tab, and the newest day is selected).</li><li><strong>DATE</strong> — choose a day; the file is loaded and shown with the filters above.</li><li><strong>Timeline replay</strong> — plays the day&#39;s log as a timeline: play / pause, step to the previous or next line, a position slider, and a speed button that cycles through 0.25× … 16×, 60×, and 300× (the fast speeds skip long quiet stretches). Tapping a line jumps to that moment. <strong>Close</strong> returns to the list.</li><li><strong>Save</strong> — saves the raw log file of the selected day to your device.</li></ol><h2 id="black-box" tabindex="-1">Black Box <a class="header-anchor" href="#black-box" aria-label="Permalink to &quot;Black Box&quot;">​</a></h2><p><img src="'+t+'" alt="Black Box replay"></p><ol><li><strong>Robot</strong> / <strong>Library</strong> — where the sessions come from: the connected robot, or the sessions kept on this device, filed by robot serial number. With no robot connected the tab opens on <strong>Library</strong>, so you can replay without the robot.</li><li><strong>Fetch</strong> — loads the list of sessions (this runs by itself the first time you open the tab).</li><li><strong>DATE</strong> and <strong>SESSION</strong> — choose a recording; the newest session of the day is opened first and the replay view is shown. In <strong>Library</strong>, <strong>S/N</strong> picks the robot first, and <strong>Delete</strong> removes the selected session from this device (the robot keeps its own copy).</li><li><strong>Timeline replay</strong> / <strong>Log list</strong> — toggles between the replay view and the plain log list of that session.</li><li><strong>Save now</strong> — asks the robot to record a black-box session right now — use it right after something looked wrong.</li><li><strong>Open zip</strong> — replays a session zip saved earlier on this device, without the robot, and keeps it in <strong>Library</strong> under the serial number found in the zip — the one the robot wrote into <code>meta.json</code>, else the one in the file name; with neither it goes under <strong>No S/N</strong>. On the <strong>Robot</strong> source, <strong>Close — to robot session</strong> returns to the robot&#39;s list.</li><li><strong>Save zip</strong> — saves the selected session (data and log) to your device and keeps a copy in <strong>Library</strong> under the robot&#39;s serial number. The file name carries the serial number too (<code>blackbox-&lt;serial&gt;-20260911_08_32_18.zip</code>): sessions recorded by older robot software do not say which robot they came from, so for those the file name is what tells the saved zips apart.</li></ol><h3 id="replay-view" tabindex="-1">Replay view <a class="header-anchor" href="#replay-view" aria-label="Permalink to &quot;Replay view&quot;">​</a></h3><ul><li>The header reads <strong>Black Box Playback</strong> with the duration, frame count, tick, and <strong>which robot the session came from</strong>. The bracket says where that came from — <code>meta.json</code> (written by the robot when it saved the session), <strong>file name</strong> (the zip&#39;s name), or <strong>connected robot</strong>. With none of the three it reads <strong>Robot unknown</strong>; sessions saved before this existed carry no stamp of their own, so they read unknown or fall back to the connection.</li><li>View buttons: <strong>Split</strong> (3D pose + log), <strong>Quad</strong> (data, log, camera, and 3D panes), <strong>3D</strong>, <strong>Data</strong>, <strong>Video</strong> (the event clip on its own), <strong>Logs</strong>.</li><li>The <strong>camera</strong> pane plays the <strong>event clips</strong> (front and rear) for that moment, and playback follows the data timeline. If the robot is still encoding them, the clips may not have arrived yet — try again in a moment. An exported zip carries the clips too, so it replays without the robot.</li><li><strong>Ref</strong> (top-right of the 3D pane) overlays the reference pose as a translucent ghost so you can compare commanded and measured joints.</li><li>The <strong>Data</strong> pane shows <strong>every recorded channel</strong> of the current frame. The <em>miss</em> chip counts control deadline misses; the number beside it is how many channels this recording holds. <ul><li>Channels are grouped into sections you can fold and unfold. <strong>JOINT</strong> starts unfolded.</li><li>Groups that are numbered or named — joints, wheels, ports — are drawn as tables: <strong>one row is one joint</strong>, carrying its angle, velocity, torque, motor current, temperatures, errors and CAN receive rate side by side. Wide tables scroll sideways inside the pane.</li><li>Type a channel name in the box at the top to keep only the groups that match (for example <code>motor.cur</code>, <code>can</code>).</li><li>Angles read in degrees; everything else keeps the unit it was recorded in. Error and miss channels turn red when they are not zero.</li><li>Channels the robot does not record get no row at all.</li></ul></li><li>The bottom bar has previous / next frame, play / pause, a slider, the wall-clock time and frame counter, and a speed button cycling 0.25× … 16×.</li><li>The <strong>SYSTEM LOG</strong> pane scrolls in step with the replay position. Tap a line to seek there. A <strong>Time sync uncertain</strong> notice appears when the recording lacks timing metadata or the clocks differ.</li></ul><h2 id="find-errors" tabindex="-1">Skimming for errors <a class="header-anchor" href="#find-errors" aria-label="Permalink to &quot;Skimming for errors {#find-errors}&quot;">​</a></h2><p>Here is how to pinpoint the moment something went wrong in a whole day of logs, in seconds.</p><ol><li>In the <strong>LEVEL</strong> chips, press <code>TRACE</code>, <code>DEBUG</code>, <code>INFO</code>, <code>SUCCESS</code>, and <code>WARNING</code> to <strong>hide</strong> them. Only <code>ERROR</code> and <code>FATAL</code> remain.</li><li>Press the <strong>next line</strong> button in the timeline replay repeatedly — it steps only between the lines that are still shown, so it jumps from error to error.</li><li><strong>Write down the timestamp</strong> where you stop (for example <code>19:30:48.855</code>).</li><li>If you need the surrounding context, turn <code>WARNING</code> or the relevant <strong>PROC</strong> chips back on there.</li></ol><p>When you do not know which process started the problem, skim with every <strong>PROC</strong> chip on, then narrow to that one process once the range is clear.</p><h2 id="for-support" tabindex="-1">What to send when you contact us <a class="header-anchor" href="#for-support" aria-label="Permalink to &quot;What to send when you contact us {#for-support}&quot;">​</a></h2><p>These three together make the cause far quicker to find.</p><ol><li><strong>The error messages</strong> — the <code>ERROR</code> and <code>FATAL</code> list you found with <a href="#find-errors">Skimming for errors</a>. Use <strong>Save</strong> to write a file, or capture the screen.</li><li><strong>The timestamp</strong> — note when the message appeared.</li><li><strong>Video from around that time</strong> — nothing settles it faster than seeing what the robot was doing.</li></ol><p>The software version and the steps to reproduce help too. For a momentary problem such as a fall or an emergency stop, include the <strong>Black Box session</strong> as well, saved with <strong>Save zip</strong>.</p><p><strong>→ <a href="/RBQ/nightly/manual/support/">Support</a></strong></p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>The battery, joint, and sensor status behind many log messages is on the <a href="/RBQ/nightly/manual/gui/dashboard.html">Dashboard</a>.</li></ul>',29)])])}const y=o(l,[["render",h]]);export{f as __pageData,y as default};
